import{_ as e,o as i,c as n,a0 as t}from"./chunks/framework.jwovEGr5.js";const h=JSON.parse('{"title":"Linux mint로 개발환경 옮기기","description":"","frontmatter":{},"headers":[],"relativePath":"inner-space/general/Linux-mint로-개발환경-옮기기.md","filePath":"inner-space/general/Linux-mint로-개발환경-옮기기.md"}'),p={name:"inner-space/general/Linux-mint로-개발환경-옮기기.md"};function l(o,a,r,c,u,m){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="linux-mint로-개발환경-옮기기" tabindex="-1">Linux mint로 개발환경 옮기기 <a class="header-anchor" href="#linux-mint로-개발환경-옮기기" aria-label="Permalink to &quot;Linux mint로 개발환경 옮기기&quot;">​</a></h1><p>나에게는 고민이 하나 있었다. 바로 집에 게이밍 사양 노트북이 하나 굴러다닌다는 것.</p><p>이를 메인 서버로 구축하기 위해, 나머지는 이에 접속하기 위한 (또는 게이밍) 용도로 사용하기 위해 개발환경을 구축해보자.</p><p>일기성 글이므로, 정보를 찾고 싶다면 다른 인터넷 글을 참고하면 좋을 것이다.</p><h2 id="준비물" tabindex="-1">준비물 <a class="header-anchor" href="#준비물" aria-label="Permalink to &quot;준비물&quot;">​</a></h2><ul><li>Linux mint가 깔린 게이밍 노트북</li><li>Mac mini</li><li>옆에서 구경할 맥북</li></ul><h2 id="_1-linux-mint로-환경-옮기기" tabindex="-1">1. Linux mint로 환경 옮기기 <a class="header-anchor" href="#_1-linux-mint로-환경-옮기기" aria-label="Permalink to &quot;1. Linux mint로 환경 옮기기&quot;">​</a></h2><p>일단 git에 올라가 있는 것을 제외하고는 icloud에서의 접근성이 더 좋으므로, Documents들을 icloud에 옮기자.</p><p>기존에 이용했던 맥북의 documents나 기본 패키지들은 정리하도록 하자.</p><p>또한 UTM을 이용해 가지고 놀던 리눅스들도 정리하도록 하자. (리눅스 마스터를 위한 rocky는 나중에 따로 고민해보자)</p><p>이제 맥미니와 맥북이 가벼워졌다.</p><p>MSI 노트북에 USB를 이용해 Linux Mint를 설치하고, 이를 켜는 기분은 굉장히 짜릿했다.</p><p>다만 짜릿한 기분도 잠시, 나는 콜맥에 세벌식을 쓰는 끔찍한 힙스터인게 생각났다. 자판 배열 설정의 지옥이 시작된 것이다.</p><h3 id="input-method-지옥" tabindex="-1">input method 지옥 <a class="header-anchor" href="#input-method-지옥" aria-label="Permalink to &quot;input method 지옥&quot;">​</a></h3><p>문제는 다음과 같았다. colemak은 기본으로 지원해줘서 설정이 쉬웠지만...</p><ol><li>세벌식 390을 사용할 경우 바닥 자판이 colemak이 되어 자판이 이상하게 섞이는 현상.</li><li>Fcitx로 세벌식을 사용할 경우 여전히 바닥 자판이 colemak이 되어버리는 현상.</li></ol><p>이를 해결하기 위해 일단 시스템 기본 자판은 English(US), 즉 기본으로 설정해놓고 Fcitx에서 colemak - 세벌식 390으로 설정해도 안됐다.</p><p>그 다음으로 써본 방법은 Fcitx5인데, 이건 각 자판마다 바닥 자판을 바꿀 수 있어서 영어 자판은 colemak으로 설정해놓고 세벌식 390의 바닥 자판을 일반 쿼티로 바꾸는 일이 가능하다.</p><p>이걸로 해결이 된 줄 알았으나....</p><p>로그인과 로그아웃을 반복할 때 가끔 자판이 쿼티로 바뀌는 문제가 생기고 말았다. 그래서 다음으로 IBus를 써보기로 했다.</p><p>IBus 또한 Hangul 자판에서 기본으로 세벌식 390을 지원한다. 그리고 기본적으로 세벌식의 바닥 자판이 쿼티이다!</p><p>다만 세벌식이 내부적으로 한영 전환을 지원하는 것이기 때문에, 설정을 잘못하면 colemak - 세벌식 390 - 세벌식 390의 쿼티 같이 괴이한 변환이 되게 된다. 다행히 이건 Start with Hangul Mode 옵션을 켜서 해결할 수 있었고... 다음 난관은...</p><h3 id="input-leap" tabindex="-1">Input Leap <a class="header-anchor" href="#input-leap" aria-label="Permalink to &quot;Input Leap&quot;">​</a></h3><p>이건 또 무슨 괴상한 앱인가. 무려 기기간에 마우스와 키보드를 공유할 수 있게 하는 미친 앱이다. 기기를 옮길 때마다 키보드 버튼과 마우스 버튼을 누르고 기다리는 과정을 없앨 수 있다!</p><p>다만 server - client로 나누어져서 설정을 따로 해줘야 하고, 같은 네트워크 안에 있어야 한다는 제약이 있긴 한데, tailscale이 있어서 문제 없나...?</p><p>일단 server로 쓰는 맥미니가 input leap 버전이 안 맞아서 서버가 안 틀어지는 억까를 겪긴 했다. 이건 금방 해결했는데, 문제는 또 자판 배열 설정이었다.</p><p>나는 맥에서도 colemak - 세벌식 390을 쓴다. 그 말은 맥에서 colemak을 쓰다가 input leap를 통해 linux mint로 이동하면 colemak의 입력이 또 colemak으로 변환되어 이상하게 꼬인다는 말이다. 이는 세벌식에서도 마찬가지이다.</p><p>해결법은 삽질을 한 시간에 비해 의외로 간단했는데, 바로 mac에서 기본 자판을 전부 abc로 바꾸면 된다는 것이다. 혹시 몰라 사용하고 있던 구름 입력기에서도 로마자 기본 자판을 abc로 설정해주었다. 단축키는 좀 꼬이겠지만, 앞으로 맥미니에는 자동화 작업을 주로 시킬 거라 상관없다.</p><p>input leap의 사용감은 걱정하던 것보단 괜찮았다. 마우스가 좀 끊기긴 하지만 못 쓸 정도는 아니었다.</p><h2 id="_2-wake-on-lan-설정하기-실패함" tabindex="-1">2. Wake-on-LAN 설정하기 (실패함) <a class="header-anchor" href="#_2-wake-on-lan-설정하기-실패함" aria-label="Permalink to &quot;2. Wake-on-LAN 설정하기 (실패함)&quot;">​</a></h2><p>기존에 귀하디 귀하신 닌텐도 스위치가 쓰던 랜선을 뽑아 노트북에 연결한 뒤, Wake-on-LAN을 설정해보자. 이는 랜선 연결을 이용해 컴퓨터를 원격으로 끄고 켤 수 있는 기능이다. 다만 보안을 위해 Tailscale은 필수이다.</p><p>근데 바이오스 설정을 하고 운영 체제에서 설정을 해봐도 도저히 안 된다. 이 프로젝트는 망했다.</p><p>다행히 절전 옵션이 잘 되어 있길래 켜놓고 오면 mac의 coffee 같은 extension 필요없이 꺼질 염려가 없는게 좋았다.</p><p>전기세는 좀 먹겠지만...</p>',34)])])}const d=e(p,[["render",l]]);export{h as __pageData,d as default};
